<?php
declare(strict_types=1);
namespace VeciAhorra\Modules\Sectorization;
final class SectorizationModule {public function register():void{add_action('rest_api_init',[$this,'routes']);add_action('admin_menu',[$this,'menu']);}public function routes():void{register_rest_route('veciahorra/v1','/sectors',['methods'=>'GET','callback'=>fn()=>new \WP_REST_Response(['success'=>true,'data'=>(new ServiceZoneRepository())->active()]),'permission_callback'=>'__return_true']);register_rest_route('veciahorra/v1','/sector/current',['methods'=>'GET','callback'=>fn()=>new \WP_REST_Response(['success'=>true,'data'=>(new CurrentSector())->current()]),'permission_callback'=>'__return_true']);register_rest_route('veciahorra/v1','/sector/current/(?P<id>\d+)',['methods'=>'POST','callback'=>function(\WP_REST_Request $r){try{return new \WP_REST_Response(['success'=>true,...$this->select($r)]);}catch(\DomainException){return new \WP_REST_Response(['success'=>false,'error'=>['code'=>'cart_conflict','message'=>'El carrito cambio o contiene productos incompatibles. Recarga antes de continuar.']],409);}catch(\InvalidArgumentException $e){return new \WP_REST_Response(['success'=>false,'error'=>['code'=>'invalid_sector','message'=>$e->getMessage()]],422);}catch(\Throwable){return new \WP_REST_Response(['success'=>false,'error'=>['code'=>'sector_persistence_failed','message'=>'No fue posible guardar la microzona. Intenta nuevamente.']],503);}},'permission_callback'=>'__return_true']);}private function select(\WP_REST_Request $r):array{$body=$r->get_json_params();$result=(new CurrentSector())->set((int)$r['id'],is_array($body)?array_intersect_key($body,array_flip(['cart_id','expected_version'])):[]);return ['data'=>$result['sector'],'cart'=>$result['cart']];}public function menu():void{add_submenu_page('veciahorra','Sectores','Sectores','manage_options','veciahorra-sectors',[$this,'page']);}public function page():void{if(!current_user_can('manage_options'))wp_die('No autorizado.');$repo=new ServiceZoneRepository();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){check_admin_referer('va_sectors');try{$repo->save($_POST,get_current_user_id());$message='Sector guardado.';}catch(\Throwable $e){$message=$e->getMessage();}}global $wpdb;$zones=$repo->all();$stores=$wpdb->get_results('SELECT id,business_name,status FROM '.$wpdb->prefix.\VeciAhorra\Core\Config::TABLE_PREFIX.'stores',ARRAY_A);require __DIR__.'/Views/admin.php';}}
